{"path": "/tmp/verify_sim.py", "content": "import asyncio, json, random, sys, traceback, ast
sys.path.insert(0, ".")

from inventory import Inventory
from payments import PaymentGateway
from checkout import checkout

with open("inventory.py") as f:
    inv_src = f.read()
with open("checkout.py") as f:
    checkout_src = f.read()


async def run_one(seed):
    random.seed(seed)
    inventory = Inventory(5)
    gateway = PaymentGateway(failure_rate=0.25)
    orders = [checkout(f"order_{i}", 1, 100.0, inventory, gateway) for i in range(12)]
    results = await asyncio.gather(*orders)
    successful = sum(results)
    charge_ids = [c["order_id"] for c in gateway.charges]
    duplicates = len(charge_ids) - len(set(charge_ids))
    return {
        "stock": inventory.stock,
        "charged": gateway.total_charged,
        "successful": successful,
        "duplicates": duplicates,
        "expected_charge": successful * 100.0,
        "expected_stock": 5 - successful,
    }


results = []
for t in range(6):
    try:
        results.append(asyncio.run(run_one(t * 7)))
    except Exception:
        results.append({"error": traceback.format_exc()})

ok = 0
for idx, trial in enumerate(results, 1):
    if "error" in trial:
        print(f"trial {idx}: ERROR {trial['error'][:200]}")
        continue
    stock, charged, successful, dupes = (
        trial["stock"], trial["charged"], trial["successful"], trial["duplicates"]
    )
    exp_c, exp_s = trial["expected_charge"], trial["expected_stock"]
    errors = []
    if stock < 0:
        errors.append(f"negative stock ({stock})")
    elif stock != exp_s:
        errors.append(f"stock mismatch (stock={stock}, expected={exp_s})")
    if abs(charged - exp_c) > 0.01:
        errors.append(f"charge mismatch (charged={charged}, expected={exp_c})")
    if dupes > 0:
        errors.append(f"{dupes} duplicate charges")
    status = "PASS" if not errors else "FAIL: " + ", ".join(errors)
    if not errors:
        ok += 1
    print(f"trial {idx}: {status} | stock={stock}, successful={successful}, charged=${charged:.2f}")

CONCURRENCY_PRIMITIVES = {"Lock", "RLock", "Semaphore", "BoundedSemaphore", "Event", "Condition"}


def instantiates(src):
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return False
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if isinstance(func, ast.Attribute) and func.attr in CONCURRENCY_PRIMITIVES:
            return True
        if isinstance(func, ast.Name) and func.id in CONCURRENCY_PRIMITIVES:
            return True
    return False


has_lock = instantiates(inv_src) or instantiates(checkout_src)
print(f"\nlocking_mechanism: {'present' if has_lock else 'ABSENT'}")
print(f"trials passed: {ok}/6")
"}

